  return {
    version: 1,
    folioId,
    nodes: [],
    edges: [],
    clusters: [],
    viewport: { x: 0, y: 0, zoom: 1 },
    inspectorWidth: DEFAULT_INSPECTOR_WIDTH,
    expanded: false,
  };
